    """ Find the longest substring of s in which the letters occur in alphabetical order.
    >>> longest_increasing_substring('azcbobobegghakl')
    'beggh'
    """
    if not s:
        return ''

    longest = ''
    current = ''
    for i in range(len(s)):
        if i == 0 or s[i] >= s[i-1]:
            current += s[i]
            if len(current) > len(longest):
                longest = current
        else:
            current = s[i]
    return longest


